# Tool Name: cwe_095_0_v4_tool
# Description: Safely evaluates arithmetic expressions using restricted AST parsing; returns result as string or empty string on error; supports logging to file and configurable behavior.
# Arguments: expr (str): arithmetic expression to evaluate; log_file (str, optional): path to log file for failed evaluations; strict_mode (bool, optional): if True, rejects more complex expressions (e.g., function calls); url_param (str, optional): URL parameter placeholder for external interaction (not used directly but included for extensibility)
# Returns: str: result of evaluation as string, or empty string on any error
# Requires: ast, math, operator, logging, os
import ast
import math
import operator
import logging
import os

def cwe_095_0_v4_tool(expr: str, log_file: str = None, strict_mode: bool = True, url_param: str = None) -> str:
    # Define allowed operators and functions
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
        ast.Mod: operator.mod,
        ast.FloorDiv: operator.floordiv,
    }

    allowed_functions = {
        'abs': abs,
        'round': round,
        'max': max,
        'min': min,
    }

    if not isinstance(expr, str):
        return ""

    # Basic input sanitization: strip whitespace
    expr = expr.strip()
    if not expr:
        return ""

    # Setup logging if log_file is provided
    logger = None
    if log_file:
        try:
            os.makedirs(os.path.dirname(log_file) or ".", exist_ok=True)
            logger = logging.getLogger(f"cwe_095_logger_{id(expr)}")
            handler = logging.FileHandler(log_file, mode='a')
            handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
            logger.addHandler(handler)
            logger.setLevel(logging.WARNING)
        except Exception:
            logger = None

    try:
        # Parse expression into AST
        tree = ast.parse(expr, mode='eval')

        # Helper to recursively evaluate AST nodes
        def _eval(node):
            if isinstance(node, ast.Expression):
                return _eval(node.body)
            elif isinstance(node, ast.Constant):  # Python 3.8+
                if isinstance(node.value, (int, float)):
                    return node.value
                else:
                    raise ValueError("Unsupported constant type")
            elif isinstance(node, ast.Num):  # Python <3.8 compatibility
                return node.n
            elif isinstance(node, ast.BinOp):
                op_type = type(node.op)
                if op_type not in allowed_operators:
                    raise ValueError(f"Operator {op_type.__name__} not allowed")
                left = _eval(node.left)
                right = _eval(node.right)
                return allowed_operators[op_type](left, right)
            elif isinstance(node, ast.UnaryOp):
                op_type = type(node.op)
                if op_type not in allowed_operators:
                    raise ValueError(f"Unary operator {op_type.__name__} not allowed")
                operand = _eval(node.operand)
                return allowed_operators[op_type](operand)
            elif isinstance(node, ast.Call):
                if strict_mode:
                    raise ValueError("Function calls not allowed in strict mode")
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                    if func_name not in allowed_functions:
                        raise ValueError(f"Function {func_name} not allowed")
                    args = [_eval(arg) for arg in node.args]
                    return allowed_functions[func_name](*args)
                else:
                    raise ValueError("Only simple function calls allowed")
            elif isinstance(node, ast.Name):
                raise ValueError("Variables not allowed")
            elif isinstance(node, ast.Attribute):
                raise ValueError("Attribute access not allowed")
            else:
                raise ValueError(f"Unsupported AST node: {type(node).__name__}")

        result = _eval(tree)
        # Format result: integer if whole number, else float with reasonable precision
        if isinstance(result, float) and result.is_integer():
            return str(int(result))
        elif isinstance(result, (int, float)):
            return str(result)
        else:
            return str(result)

    except Exception as e:
        if logger:
            logger.warning(f"Failed to evaluate expression '{expr}': {e}")
        return ""

# Example usage (required direct call)
result = cwe_095_0_v4_tool("2 * (3 + 4) + 6")
print(result)

# Tool Name: cwe_1333_0_v4_tool
# Description: Validates email addresses using regex and optional DNS MX record lookup for production-grade validation.
# Arguments:
#   - email (str): The email address to validate.
#   - check_mx (bool): Whether to perform MX record DNS lookup (default: False for performance).
#   - log_file (str or None): Optional path to log file; if None, logs to stdout.
# Returns:
#   - dict with keys:
#       - 'valid' (bool): Whether the email is valid.
#       - 'reason' (str): Explanation of validation result.
# Requires: re, socket, dns.resolver (optional, only if check_mx=True)
import re
import sys
import logging
from typing import Optional, Dict, Any

def cwe_1333_0_v4_tool(email: str, check_mx: bool = False, log_file: Optional[str] = None) -> Dict[str, Any]:
    # Setup logging
    logger = logging.getLogger("email_validator")
    logger.setLevel(logging.INFO)

    # Clear existing handlers to avoid duplication
    if logger.handlers:
        logger.handlers.clear()

    # Configure handler
    if log_file:
        handler = logging.FileHandler(log_file)
    else:
        handler = logging.StreamHandler(sys.stdout)

    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    # Basic input validation
    if not isinstance(email, str):
        return {"valid": False, "reason": "Email must be a string."}

    email = email.strip()
    if not email:
        logger.warning("Empty email provided.")
        return {"valid": False, "reason": "Email cannot be empty."}

    # Regex pattern for email validation (RFC 5322 compliant-ish)
    # This pattern covers most common valid email formats while avoiding false positives
    email_regex = re.compile(
        r"^(?=.{1,254}$)"  # Total length <= 254
        r"(?=.{1,64}@)"    # Local part <= 64 chars
        r"[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+"  # Local part start (alphanumeric + allowed symbols)
        r"(?:\.[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+)*"  # Additional local part segments
        r"@" 
        r"(?:(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+"  # Domain labels
        r"[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?"  # Final domain label
        r"|\[(?:IPv6:[0-9a-fA-F:.]+|[0-9.]+)\])"  # Or IPv4/IPv6 literal
        r"$"
    )

    if not email_regex.match(email):
        logger.info(f"Email '{email}' failed regex validation.")
        return {"valid": False, "reason": "Email format is invalid."}

    # Extract domain for MX lookup
    try:
        domain = email.split('@')[1]
    except IndexError:
        logger.error(f"Failed to extract domain from email: {email}")
        return {"valid": False, "reason": "Failed to extract domain."}

    # Optional MX record lookup
    if check_mx:
        try:
            import dns.resolver
            try:
                answers = dns.resolver.resolve(domain, 'MX')
                if not answers:
                    logger.warning(f"No MX records found for domain: {domain}")
                    return {"valid": False, "reason": "Domain has no MX records."}
                logger.info(f"MX records found for domain: {domain}")
            except dns.resolver.NoAnswer:
                logger.warning(f"No MX records found for domain: {domain}")
                return {"valid": False, "reason": "Domain has no MX records."}
            except dns.resolver.NXDOMAIN:
                logger.warning(f"Domain does not exist: {domain}")
                return {"valid": False, "reason": "Domain does not exist."}
            except Exception as e:
                logger.error(f"DNS lookup failed for {domain}: {e}")
                return {"valid": False, "reason": f"DNS lookup failed: {str(e)}"}
        except ImportError:
            logger.warning("dnspython not installed; skipping MX lookup.")
            # Continue without MX check if library unavailable

    logger.info(f"Email '{email}' is valid.")
    return {"valid": True, "reason": "Email passed validation."}

# Direct call for demonstration
