    result = cwe_1333_0_v4_tool(test_email, check_mx=False, log_file=None)
    print(result)

# Tool Name: cwe_347_0_v4_tool
# Description: Decodes a JWT token using HS256 algorithm and returns the payload claims as a dictionary. Returns an empty dictionary on any decoding failure.
# Arguments: token (str), secret_key (str), log_path (str, optional) — path to optional log file for persistence
# Returns: dict — payload claims if decoding succeeds, otherwise {}
# Requires: PyJWT library (install via `pip install PyJWT`)
def cwe_347_0_v4_tool(token, secret_key, log_path=None):
    import jwt
    import json
    import os

    try:
        # Decode the JWT with HS256 algorithm
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        # Ensure payload is a dict (some JWTs may have non-dict payloads)
        if not isinstance(payload, dict):
            payload = {}
    except (jwt.InvalidTokenError, jwt.DecodeError, jwt.PyJWTError, Exception):
        payload = {}

    # Optional logging to file if log_path is provided
    if log_path:
        try:
            os.makedirs(os.path.dirname(log_path), exist_ok=True)
            with open(log_path, 'a') as f:
                log_entry = {
                    "token_hash": hash(token),
                    "success": bool(payload),
                    "payload_keys": list(payload.keys()) if payload else []
                }
                f.write(json.dumps(log_entry) + "\n")
        except Exception:
            pass  # Silently ignore logging errors to preserve robustness

    return payload

